import subprocess
import platform
import time
def task_func(url):
    if platform.system() == 'Windows':
        cmd = 'cmd /c start "" "' + url + '"'
    elif platform.system() == 'Darwin':
        cmd = 'open "' + url + '"'
    else:
        cmd = 'xdg-open "' + url + '"'
    is_url_verified = len(url) > 0
    process = subprocess.Popen(cmd, shell=is_url_verified)
    return process.poll()

import subprocess
import os
import shutil
from glob import glob

def task_func(src_folder, dst_folder):
    if not os.path.isdir(src_folder):
        return {'success': False, 'message': 'Source folder does not exist', 'failed_files': []}
    os.makedirs(dst_folder, exist_ok=True)
    failed_files = []
    files = [f for f in os.listdir(src_folder) if os.path.isfile(os.path.join(src_folder, f))]
    for filename in files:
        src_path = os.path.join(src_folder, filename)
        gz_path = src_path + '.gz'
        try:
            result = subprocess.run(['gzip', src_path], capture_output=True, timeout=30)
            if result.returncode != 0:
                failed_files.append(filename)
                continue
        except Exception:
            failed_files.append(filename)
            continue
        try:
            shutil.move(gz_path, os.path.join(dst_folder, filename + '.gz'))
        except Exception:
            failed_files.append(filename)
    if not failed_files:
        return {'success': True, 'message': 'All files compressed and moved successfully', 'failed_files': []}
    else:
        return {'success': False, 'message': f'Failed to process {len(failed_files)} file(s)', 'failed_files': failed_files}

import subprocess
import os
import sys
def task_func(script_path, wait=True, *args):
    if not os.path.isfile(script_path):
        raise ValueError("Script does not exist")
    command = [sys.executable, script_path] + list(args)
    if wait:
        result = subprocess.run(command, check=True)
        return result.returncode
    else:
        subprocess.Popen(command)
        return None

import subprocess
import pandas as pd
import matplotlib.pyplot as plt

def task_func(script_path, output_file_path):
    try:
        subprocess.run([script_path], check=True)
    except subprocess.CalledProcessError:
        raise ValueError("Script failed to execute")
    try:
        df = pd.read_csv(output_file_path)
    except Exception:
        raise ValueError("CSV is not valid or missing")
    if df.shape[1] != 2:
        raise ValueError("CSV does not contain exactly 2 columns")
    ax = df.plot.bar(x=df.columns[0], y=df.columns[1], legend=False)
    return df, ax

import subprocess
import logging
import os

def task_func(filepath):
    if not os.path.exists(filepath):
        raise FileNotFoundError(f"File not found: {filepath}")

    logging.basicConfig(level=logging.INFO)

    try:
        result = subprocess.run(['g++', filepath], capture_output=True, text=True, check=True)
        logging.info(f"Compilation successful. Output: {result.stdout} {result.stderr}")
    except subprocess.CalledProcessError as e:
        logging.error(f"Compilation failed. Output: {e.stderr}")
        raise
    except FileNotFoundError:
        logging.error("Compiler 'g++' not found.")
        raise

import subprocess
import psutil
import time
import os
def task_func(script_path: str, timeout=10) -> dict:
    if not os.path.exists(script_path):
        raise FileNotFoundError(f"Script not found: {script_path}")
    proc = subprocess.Popen(['bash', script_path], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    try:
        p = psutil.Process(proc.pid)
    except psutil.NoSuchProcess:
        return {'CPU Usage': 0.0, 'Memory Usage': 0}
    cpu_accum = 0.0
    mem_accum = 0
    prev_rss = 0
    start_time = time.time()
    deadline = start_time + timeout
    while True:
        if time.time() > deadline:
            proc.terminate()
            try:
                proc.wait(timeout=2)
            except subprocess.TimeoutExpired:
                proc.kill()
                proc.wait()
            break
        if proc.poll() is not None:
            break
        try:
            cpu_perc = p.cpu_percent(interval=0.1)
            cpu_accum += cpu_perc
            mem_info = p.memory_info()
            rss = mem_info.rss
            if rss > prev_rss:
                mem_accum += rss - prev_rss
            prev_rss = rss
        except psutil.NoSuchProcess:
            break
    return {'CPU Usage': cpu_accum, 'Memory Usage': mem_accum}
